                    state.generation != generation
                        || (!state.complete && state.retry_at.is_none_or(|at| at <= now))
                })
            })
        else {
            quiet_turn = true;
            return Ok(None);
        };
        selected_channel = Some(channel);
        let state = cursors.entry(channel).or_default();
        if state.generation != generation {
            state.generation = generation;
            state.restart_sweep();
            state.retry_at = None;
            state.backoff.reset();
