                    .is_empty()
            {
                missing_report = select_custody_peer(report_peers.clone(), cycle)
                    .map(|peer| (channel, event_id, peer));
            }
            let target = members
                .iter()
                .filter_map(|member| {
                    self.channel_custody_member_principal(channel, member, None)
                })
                .collect::<HashSet<_>>()
                .len()
                .min(2);
            if target == 0
                || self
