        let mut confirmed = self
            .channel_custody
            .lock()
            .expect("custody mutex")
            .peers(id)?;
        for meta in &observations {
            if let super::account_documents::AccountDocumentKey::ChannelCustody { holder, .. } =
                &meta.key
