const MAGIC: &[u8; 6] = b"MTRTE1";
const MAX_BYTES: u64 = 1_048_576;
const HEADER: usize = MAGIC.len() + SALT_SIZE + NONCE_SIZE;
fn invalid() -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, "invalid routing cache")
}
fn bad<T>(_: T) -> io::Error {
    invalid()
