async fn privacy_dial_inner(
    &self,
    addr: std::net::SocketAddr,
    expected: &PublicIdentity,
    priority: super::session_pool::AuthenticationPriority,
    interactive: bool,
    watch: bool,
) -> Result<SecureChannel<TcpStream>, TransportError> {
    #[cfg(test)]
    let mut timing = super::delivery_runtime::TestTiming::new("dial-own-presence");
    let mut addr = addr;
    addr.set_ip(crate::transport::net::canonical_peer_ip(addr.ip()));
    #[cfg(test)]
    timing.phase("dial-privacy-gate");
    #[cfg(test)]
    self.trace_account_client(expected, || "dial_privacy_gate_wait".into());
    let _operation = self.privacy.gate.read().await;
    #[cfg(test)]
    self.trace_account_client(expected, || "dial_privacy_gate_acquired".into());
    let own = self.own_presence();
    let transitions = self.own_account_transitions();
    #[cfg(test)]
    timing.phase("dial-admission");
    let announce = self
        .roster
        .lock()
        .expect("roster lock not poisoned")
        .announcement(expected)
        .cloned();
    if !self.account_allowed(expected, announce.as_ref())
        && !self
            .group_member(expected)
            .map_err(|error| TransportError::Io(io::Error::other(error)))?
        && !self.group_departure_peer(expected)
    {
        return Err(TransportError::AdmissionDenied);
    }
    #[cfg(test)]
    self.trace_account_client(expected, || "dial_policy_admitted".into());
    let candidates = self.privacy_route_candidates(addr, expected, announce.as_ref());
    // A departed LAN endpoint may still accept TCP through a proxy/TUN but
    // never complete Noise. Give a second verified candidate a turn after
    // 200ms instead of serially spending a whole handshake deadline there.
    // Futures are owned here: returning/cancellation drops every loser.
    use futures_util::{StreamExt, stream::FuturesUnordered};
    let attempt = |candidate| {
        let own = own.as_ref();
        let transitions = transitions.as_slice();
        async move {
            let result = async {
                #[cfg(test)]
                self.trace_account_client(expected, || {
                    "dial_authentication_admission_wait".into()
                });
                let authentication_key = self.peer_endpoint_key(candidate, expected);
                let _authentication = match priority {
                    super::session_pool::AuthenticationPriority::Ordinary => {
                        self.sessions
                            .authentication_admission(authentication_key.clone())
                            .await?
                    }
                    super::session_pool::AuthenticationPriority::Control => {
                        self.sessions
                            .authentication_admission_priority(authentication_key.clone(), priority)
                            .await?
                    }
                };
                // Re-evaluate freshness after the per-endpoint wait. An
                // old failure cannot suppress newly eligible discovery.
                let historical = !interactive && self.historical_route_candidate(candidate, expected, std::time::Instant::now());
                let mut historical_attempt = if historical {
                    Some(self.sessions.historical_authentication(&authentication_key,
                        *self.network_changes.borrow(), std::time::Instant::now())?)
                } else { None };
                let _historical = historical
                    .then(|| self.sessions.historical_dial())
                    .transpose()?;
                #[cfg(test)]
                self.trace_account_client(expected, || {
                    "dial_authentication_admission_acquired_outbound_wait".into()
                });
                let permits = if watch {
                    self.sessions.watch_outbound().await?
                } else {
                    self.sessions.outbound().await?
                };
                #[cfg(test)]
                self.trace_account_client(expected, || "dial_outbound_acquired".into());
                let started = std::time::Instant::now();
                let result = tokio::time::timeout(
                    self.sessions.authentication_timeout(expected, candidate),
                    async {
                        #[cfg(test)]
                        self.trace_account_client(expected, || "dial_tcp_connect_begin".into());
                        let stream = TcpStream::connect(candidate).await?;
                        #[cfg(test)]
                        self.trace_account_client(expected, || "dial_tcp_connect_end".into());
                        #[cfg(test)]
                        self.trace_account_client(expected, || {
                            format!(
                                "dial_socket_ports={:?}",
                                (
                                    stream.local_addr().ok().map(|addr| addr.port()),
                                    stream.peer_addr().ok().map(|addr| addr.port())
                                )
                            )
                        });
                        stream.set_nodelay(true)?;
                        crate::transport::net::set_tcp_keepalive(&stream);
                        let publicly_visible = self.publicly_visible_at(stream.peer_addr()?);
                        #[cfg(test)]
                        self.trace_account_client(expected, || "dial_noise_begin".into());
                        SecureChannel::connect_with_transitions(
                            stream,
                            &self.identity,
                            Some(expected),
                            own,
                            publicly_visible,
                            transitions,
                        )
                        .await
                    },
                )
                .await
                .unwrap_or_else(|_| {
                    self.sessions.authentication_timed_out(expected, candidate);
                    Err(TransportError::Noise("dial timed out".into()))
                });
                if let Some(attempt) = &mut historical_attempt {
                    attempt.complete(result.is_ok(), std::time::Instant::now());
                }
                #[cfg(test)]
                self.trace_account_client(expected, || {
                    format!(
                        "dial_noise_end ok={} outcome={:?}",
                        result.is_ok(),
                        super::account_session::client_transport_outcome(&result)
                    )
                });
                let elapsed = started.elapsed();
                if elapsed >= Duration::from_secs(2) {
                    log::debug!(target: "mesh_talk::delivery",
                        "slow peer authentication endpoint={} elapsed_ms={} authenticated={} historical={} interactive={}",
                        candidate, elapsed.as_millis(), result.is_ok(), historical, interactive);
                    if let Some(summary) = self.sessions.observe_slow_authentication(elapsed, result.is_ok(), historical, interactive) {
                        log::warn!(target: "mesh_talk::delivery",
                            "slow peer authentication summary attempts={} failures={} historical={} max_elapsed_ms={} last_endpoint={} interactive={}",
                            summary.attempts, summary.failures, summary.historical, summary.longest.as_millis(), candidate, interactive);
                    }
                }
                result.map(|channel| (channel, permits, started.elapsed()))
            }
            .await;
            (candidate, result)
        }
    };
    let mut candidates = candidates.into_iter().peekable();
    let mut attempts = FuturesUnordered::new();
    if let Some(candidate) = candidates.next() {
        attempts.push(attempt(candidate));
    }
    let mut stagger = tokio::time::interval(Duration::from_millis(200));
    stagger.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    stagger.tick().await;
    let mut last_error = TransportError::Noise("no peer route available".into());
    let mut successful = None;
    while !attempts.is_empty() {
        tokio::select! {
            result = attempts.next() => {
                let Some((candidate, result)) = result else { break };
                match result {
                    Ok((channel, permits, elapsed)) => {
                        successful = Some((candidate, channel, permits, elapsed));
                        break;
                    }
                    Err(error) => {
                        last_error = error;
                        if let Some(candidate) = candidates.next() {
                            attempts.push(attempt(candidate));
                        }
                    }
                }
            }
            _ = stagger.tick(), if attempts.len() < 2 && candidates.peek().is_some() => {
                attempts.push(attempt(candidates.next().expect("candidate available")));
            }
        }
    }

