 * a Save action. Reuses the shared MediaPreview (lazy bytes + revoked blob URLs). */
function FileBubble({
  file,
  mine,
  metadataPending,
  failed,
  sendKey,
  messageId,
  isChannel,
  isPersonal,
  readOnly,
}: {
  file: NonNullable<ChatMessage["file"]>;
  mine: boolean;
  metadataPending?: boolean;
  failed?: boolean;
  sendKey?: string;
  messageId?: string | null;
  isChannel: boolean;
  isPersonal: boolean;
  readOnly: boolean;
}) {
  const { t } = useTranslation();
  const setError = useChat((s) => s.setError);
  const savedPath = useSavedDownloads()[file.fileConv];
  const status = useFileStatus(
    savedPath ? undefined : file.fileConv || undefined,
  );
  const available = !!savedPath || !!status?.ready;
  const [saving, setSaving] = useState(false);
  const autoFailure = useAutomaticDownloads((s) => s.failures[file.fileConv]);
  const automatic = useChat(
    (s) =>
      !mine &&
      s.incomingFiles.some((entry) => entry.fileConv === file.fileConv),
  );
  const directory = isDirectoryAttachment(file.mime);
  const approvalNeeded =
    !mine && (status?.consent === "pending" || status?.consent === "declined");
  const uploadKey =
    mine && !metadataPending && !isChannel && !isPersonal
      ? messageId || undefined
      : undefined;

  const saveAs = async () => {
    const lease = captureChatOwnership();
    if (
      !lease.current() ||
      metadataPending ||
      !file.fileConv ||
      !available ||
      saving
    )
      return;
    try {
      setSaving(true);
      await saveAttachment(file, lease, {
        mode: directory ? "default" : "as",
      });
    } catch (e) {
      if (lease.current() && markUnavailableFileError(file.fileConv, e)) return;
      if (lease.current())
        setError(t("files.couldntSave", { error: errorMessage(e) }));
    } finally {
      setSaving(false);
    }
  };

  const reveal = async () => {
    if (!savedPath) return;
    const lease = captureChatOwnership();
    try {
      await revealItemInDir(savedPath);
    } catch (e) {
      if (lease.current())
        setError(t("files.couldntOpen", { error: errorMessage(e) }));
    }
  };

  const decideAttachment = createAttachmentDecision({
    captureOwnership: captureChatOwnership,
    decideAttachment: chat.decideAttachment,
    refreshAvailability: refreshFileAvailability,
    reportError: (error) =>
      setError(t("files.approvalFailed", { error: errorMessage(error) })),
  });
  const decide = (accept: boolean) => decideAttachment(file.fileConv, accept);

  // Media (image/video, sent via the media button) that is small enough to render inline:
  // show ONLY the preview. Its filename, size, and download live in the detail view that
  // opens on click (MediaPreview's lightbox) — the chat doesn't need that clutter under
  // every photo. Media that is too large to preview inline falls through to the file card
  // below, so it stays visible and savable instead of rendering an empty bubble.
  if (
    !metadataPending &&
    !approvalNeeded &&
    file.fileConv &&
    file.media &&
    withinInlineCap(file.name, file.size)
  ) {
    return (
      <div data-inline-media="" className="max-w-xs">
        <MediaPreview
          fileConv={file.fileConv}
          name={file.name}
          size={file.size}
          mime={file.mime}
          readOnly={readOnly}
        />
        {uploadKey && (
          <TransferBar
            transferKey={uploadKey}
            waitingDirection={sendKey ? "send" : undefined}
          />
        )}
      </div>
    );
  }

  // Attachment (or over-cap media): the file card IS the content — name + size + download.
  return (
    <div className="min-w-[12rem] max-w-xs">
      {!readOnly &&
        !metadataPending &&
        !approvalNeeded &&
        available &&
        isForwardedRecord(file.name, file.mime) && (
          <ForwardedRecordPreview
            fileConv={file.fileConv}
            name={file.name}
            size={file.size}
            mime={file.mime}
          />
        )}
      <div className="flex items-center gap-2">
        {fileGlyph(file.name, file.mime)}
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm">
            {attachmentLabel(file.name, file.mime, file, t("message.sticker"))}
          </div>
          <div className="font-mono text-[11px] tabular-nums opacity-70">
            {metadataPending
              ? t(
                  failed
                    ? "message.fail.unknown"
                    : "message.delivery.metadataPending",
                )
              : readOnly && !available
                ? t("recovery.mediaUnavailable")
                : humanSize(file.size)}
          </div>
        </div>
        <button
          type="button"
          onClick={() => {
            if (savedPath) void reveal();
            else if (automatic) retryAutomaticDownload(file.fileConv);
            else void saveAs();
          }}
          disabled={
            metadataPending ||
            !file.fileConv ||
            (!savedPath &&
              (!available || saving || (automatic && !autoFailure)))
          }
          title={
            metadataPending
              ? t("transfer.sending")
              : !available
                ? t(readOnly ? "recovery.mediaUnavailable" : "transfer.waiting")
                : savedPath
                  ? t("files.savedTo", { path: savedPath })
                  : t(
                      automatic
                        ? autoFailure
                          ? "contactVisibility.retry"
                          : "common.loading"
                        : "common.save",
                    )
          }
          aria-label={
            savedPath
              ? t("files.reveal")
              : t(
                  automatic
                    ? autoFailure
                      ? "contactVisibility.retry"
                      : "common.loading"
                    : "common.save",
                )
          }
          data-download-error={autoFailure || undefined}
          className={cn(
            "rounded-md p-1 transition-colors disabled:cursor-not-allowed disabled:opacity-40",
            mine
              ? "text-primary-foreground/80 hover:bg-primary-foreground/15"
              : "text-muted-foreground hover:bg-accent hover:text-foreground",
          )}
        >
          {savedPath ? (
            <FolderOpen className="h-4 w-4" />
          ) : (
            <Download className="h-4 w-4" />
          )}
        </button>
      </div>
      {metadataPending && mine && !failed && (
        <TransferBar transferKey={sendKey} waitingDirection="prepare" />
      )}
      {uploadKey && (
        <TransferBar
          transferKey={uploadKey}
          waitingDirection={sendKey ? "send" : undefined}
        />
      )}
      {autoFailure && (
        <div role="alert" className="mt-1 text-xs text-destructive">
          {t("files.couldntSave", { error: autoFailure })}
        </div>
      )}
      {!readOnly && !mine && !metadataPending && !savedPath && (
        <ReceiveProgress status={status} />
      )}
      {!readOnly && approvalNeeded && !savedPath && (
        <div className="mt-2 flex gap-2">
          <button
            data-testid="receive-file"
            type="button"
            onClick={() => void decide(true)}
            className="rounded-md bg-primary px-2.5 py-1 text-xs text-primary-foreground"
            aria-label={t("files.approve")}
          >
            {t("files.approve")}
                data-context-menu=""
                className={cn(
                  "min-w-0 text-[14px] leading-[1.55]",
                  // Stickers float; actual inline media removes its text-bubble shell.
                  // File cards and consent prompts retain the ordinary bubble.
                  isSticker
                    ? ""
                    : cn(
                        "rounded-xl px-3.5 py-2.5 [&:has([data-inline-media])]:border-0 [&:has([data-inline-media])]:bg-transparent [&:has([data-inline-media])]:p-0",
                        mine
                          ? "rounded-br-sm bg-bubble-own text-[hsl(var(--bubble-own-foreground))]"
                          : "rounded-bl-sm border border-border bg-muted text-foreground",
                      ),
                  mentioned && "ring-1 ring-inset ring-signal/65",
                  m.pending && "opacity-75",
                )}
              >
                {m.protection ? (
                  <ProtectedMessage
                    id={m.id}
                    protection={m.protection}
                    image={!!m.file}
                    mime={m.file?.mime}
                  />
                ) : mediaSticker ? (
                  <MediaSticker
                    key={m.file!.fileConv || m.clientId}
                    fileConv={m.file!.fileConv}
                    mime={m.file!.mime}
                    fallback={mediaSticker.fallback}
                    label={presentation?.label}
                    readOnly={readOnly}
                  />
                ) : isSticker ? (
                  sticker ? (
                    <img
                      src={sticker.url}
                      alt={stickerDescription}
                      title={presentation?.label}
                      data-testid="message-sticker"
                      draggable={false}
                      className="h-32 w-32 max-w-full select-none object-contain"
                    />
                  ) : (
                    // Version skew: peer sent a sticker this build doesn't bundle → show
                    // the fallback emoji char big.
                    <span
                      data-testid="message-sticker-fallback"
                      role="img"
                      aria-label={stickerDescription}
                      className="text-6xl"
                    >
                      {displayedText}
                    </span>
                  )
                ) : isFile ? (
                  <FileBubble
                    file={m.file!}
                    mine={mine}
                    metadataPending={m.metadataPending}
                    failed={m.failed}
                    sendKey={m.clientId}
                    messageId={m.id}
                    isChannel={isChannel}
                    isPersonal={isPersonal}
                    readOnly={readOnly}
                  />
                ) : (
                  <span className="cursor-text select-text whitespace-pre-wrap [overflow-wrap:anywhere]">
                    {renderWithMentions(displayedText, { ownBubble: mine })}
                  </span>
import { useCallback, useLayoutEffect, useRef, useState } from "react";
import { captureChatOwnership } from "@/store/chat";
import type { OutgoingMediaPreview } from "@/store/outgoingMediaPreviews";
import { useMotionOK } from "@/lib/motion";
import { useTranslation } from "react-i18next";
import { useFileStatus } from "@/store/fileAvailability";
import { useFileObjectUrl } from "./mediaFile";
import { ReceiveProgress } from "./ReceiveProgress";
import { stickerSummary } from "@/lib/stickerMedia";

/** Artwork belongs to the received manifest, independently of installed packs. */
export function MediaSticker({
  fileConv,
  mime,
  fallback,
  label,
  readOnly = false,
  localPreview,
}: {
  fileConv: string;
  mime: string;
  fallback: string;
  label?: string;
  readOnly?: boolean;
  localPreview?: OutgoingMediaPreview;
}) {
  const { t } = useTranslation();
  const motionOK = useMotionOK();
  const description = stickerSummary({ label }, t("message.sticker"));
  const status = useFileStatus(fileConv || undefined);
  const [readFailed, setReadFailed] = useState(false);
  const [retryKey, setRetryKey] = useState(0);
  const onReadError = useCallback(() => setReadFailed(true), []);
  const url = useFileObjectUrl(
    fileConv,
    !!status?.ready && !status.unavailable,
    mime,
    { onReadError, retryKey, reuse: true },
  );
  const [failedUrl, setFailedUrl] = useState<string | null>(null);
  const [decodedUrl, setDecodedUrl] = useState<string | null>(null);
  const source = useRef<{ fileConv: string; url: string | null } | null>(null);
  useLayoutEffect(() => {
    source.current = { fileConv, url };
    return () => {
      source.current = null;
    };
  }, [fileConv, url]);
  const lease = captureChatOwnership();
  const currentImage = (image: HTMLImageElement) =>
    lease.current() &&
    source.current?.fileConv === fileConv &&
    source.current.url === url &&
    image.getAttribute("src") === url;
  const preview =
    !readOnly && localPreview?.current() ? localPreview : undefined;
  const durable = !!url && failedUrl !== url;
  const decoded = durable && decodedUrl === url;
  return (
    <div className="w-32 max-w-full space-y-2 text-center">
      <div className="relative h-32 w-32 max-w-full">
        {!decoded &&
          (preview ? (
            <img
              src={preview.url}
              alt={description}
              title={label}
              draggable={false}
              className="absolute inset-0 h-32 w-32 max-w-full select-none object-contain"
            />
          ) : (
            <span
              data-testid="message-sticker-fallback"
              role="img"
              aria-label={description}
              className="inline-flex h-32 w-32 max-w-full items-center justify-center text-6xl"
            >
              {fallback}
            </span>
          ))}
        {durable && (
          <img
            key={url}
            src={url}
            alt={description}
            title={label}
            data-testid="message-sticker"
            draggable={false}
            onLoad={(event) => {
              if (
                !currentImage(event.currentTarget) ||
                !event.currentTarget.naturalWidth ||
                !event.currentTarget.naturalHeight
              )
                return;
              setDecodedUrl(url);
              if (preview?.current()) preview.release();
            }}
            onError={(event) => {
              if (currentImage(event.currentTarget)) setFailedUrl(url);
            }}
            className="absolute inset-0 h-32 w-32 max-w-full select-none object-contain"
            style={{
              opacity: decoded ? 1 : 0,
              transition: preview
                ? undefined
                : `opacity ${motionOK ? 180 : 80}ms cubic-bezier(0.22, 1, 0.36, 1)`,
            }}
          />
        )}
      </div>
      {(failedUrl && url) ||
      (readFailed && status?.ready && !status.unavailable) ? (
        <div className="text-xs text-muted-foreground">
          <p role="status">
            {t(url ? "files.imageUnsupported" : "files.unavailable")}
          </p>
          {!readOnly && (
            <button
              type="button"
              onClick={() => {
                setFailedUrl(null);
                setReadFailed(false);
                setRetryKey((key) => key + 1);
              }}
              className="mt-1 rounded-md border px-2 py-1 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {t("common.retry")}
            </button>
          )}
        </div>
      ) : decoded || preview ? null : status?.ready ? (
        <p role="status" className="text-xs text-muted-foreground">
          {t("common.loading")}
        </p>
      ) : (
        <ReceiveProgress status={status} />
      )}
    </div>
  );
}

