  const keys = await page.evaluate(() =>
    (
      window as unknown as {
        __sendProgress: { requests: Array<{ key: string }> };
      }
    ).__sendProgress.requests.map((r) => r.key),
  );
  expect(keys[0]).not.toBe(keys[1]);
