  mime: string,
): { width: number; height: number } | undefined {
  const u16le = (at: number) => bytes[at] | (bytes[at + 1] << 8);
  const u16be = (at: number) => (bytes[at] << 8) | bytes[at + 1];
  const u32be = (at: number) =>
    (bytes[at] * 0x1000000 +
      (bytes[at + 1] << 16) +
      (bytes[at + 2] << 8) +
      bytes[at + 3]) >>>
