it("coalesces busy invalidations to the latest input", async () => {
  let release!: () => void;
  const held = new Promise<void>((resolve) => {
    release = resolve;
  });
  const observed: (number | undefined)[] = [];
  const refresh = createRosterRefresh<number>({
    capture: () => ({ current: () => true }),
