export async function signedPeerObservation({ peer, userId, peerName, observe, until, publiclyVisible = true }) {
  // Sign-out/sign-in creates a fresh node. Discovery is asynchronous: the old
  // CLI output is not proof that the replacement UI node has rediscovered it.
  const rawPeer = await until("restarted UI rediscovers signed CLI identity", async () =>
    (await observe("list_peers")).find(p => p.name === peerName));
  // A private UI node keeps its route available without joining the CLI's
  // public roster. The caller verifies the return route with a real DM.
  if (!publiclyVisible) return rawPeer;
  let outputStart = peer.output.length;
  await until("fresh CLI roster sees UI node", async () => {
    if (peer.output.slice(outputStart).includes(`peer ${userId}`)) return true;
    // Discovery in the opposite direction may also lag. A single empty roster
    // response cannot become successful unless we actually query it again.
    outputStart = peer.output.length;
    await writeChildCommand(peer, "/peers\n");
    return peer.output.slice(outputStart).includes(`peer ${userId}`);
  });
  return rawPeer;
}

// Runtime assertions against the owned native webview, real CLI, and read-only
// production observations. This module does not replace any application IPC.
import assert from "node:assert/strict";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

export function writeChildCommand(child, text) {
  return new Promise((resolve, reject) => {
    const stream = child.stdin;
    if (!stream || stream.destroyed || !stream.writable || stream.writableEnded) {
      reject(new Error("Owned child stdin is not writable"));
      return;
    }
    stream.once("error", reject);
    try {
      stream.write(text, error => {
        if (error) reject(error);
        else { stream.removeListener("error", reject); resolve(); }
      });
    } catch (error) { reject(error); }
  });
}

/** Keep attachment output inside the disposable profile, independent of OS home folders. */
export async function prepareNativeDownloadFixture({ fixture, owner, invoke }) {
  assert.ok(owner, "native download setup requires the signed-in fixture owner");
  const directory = join(fixture, "downloads");
  await mkdir(directory, { recursive: true });
  const expectedAccount = await invoke("account_id", {});
  assert.match(typeof expectedAccount === "string" ? expectedAccount : "", /^[0-9a-f]{32}$/, "native download setup requires the current account");
  const settings = await invoke("get_app_settings", { owner });
  await invoke("set_app_settings", { owner, expectedAccount, settings: { ...settings, download_dir: directory }, patch: { download_dir: directory } });
  assert.equal((await invoke("get_app_settings", { owner })).download_dir, directory, "production settings retain the owned download directory");
  return directory;
}

/** Failure-only observations; requests retain the native driver's existing bounds. */
export async function attachmentFailureContext(c, { senderDevice, fileName, outputOffset }) {
  const metadata = rows => rows.slice(-50).map(({ id, from_me, file }) => ({
    id, from_me, file: file ? { file_conv: file.file_conv, name: file.name?.slice(0, 256), size: file.size, media: file.media } : undefined,
  }));
  const reads = [
    ["my_id", {}], ["account_id", {}], ["diag_get_peers", {}],
    ["history", { peer: senderDevice, limit: 50 }],
    ["account_history", { account: c.account, limit: 50 }],
  ];
  const snapshot = Object.fromEntries(await Promise.all(reads.map(async ([name, args]) => {
    try {
      const value = await c.observe(name, args);
      return [name, name.endsWith("history") ? metadata(value)
        : name === "diag_get_peers" ? value.slice(0, 32).map(({ user_id, account_id, ip, tcp_port, last_seen_secs }) => ({ user_id, account_id, ip, tcp_port, last_seen_secs })) : value];
    } catch { return [name, { observationFailed: true }]; }
  })));
  const output = c.peer.output.slice(Math.max(outputOffset, c.peer.output.length - 8192));
  return { ...snapshot, expected: { senderDevice, recipientDevice: c.userId, senderAccount: c.account, fileName },
    send: { accepted: output.split(/\r?\n/u).includes(`file sent to ${c.userId}`), failed: /(?:^|\n)file send failed:/u.test(output) } };
}

/** A successful automatic export is durable evidence even after transient chunks retire. */
export async function verifyNativeAttachmentDownload(c, path, expected) {
  return c.until("incoming attachment exact decrypted download bytes available", async () => {
    let actual;
