    pos=5
    def take(n):
        nonlocal pos
        value=body[pos:pos+n]; assert len(value)==n; pos+=n; return value
    def number(fmt): return struct.unpack(fmt,take(struct.calcsize(fmt)))[0]
    def string():
        length=number('<Q'); assert length<=1024;return take(length).decode()
